sys_variable_value.value:
(function execute(inputs, outputs) {
    // Here we assume table is scheduled_import_set
    var gr_import_set = new GlideRecord("scheduled_import_set");
    gr_import_set.addQuery("name", inputs.job_name);
    gr_import_set.addQuery("sys_scope", gs.getCurrentApplicationId());
    gr_import_set.setLimit(1);
    gr_import_set.query();
    gr_import_set.next();
    outputs.job_record = gr_import_set;
})(inputs, outputs);

